  // ═══════════════════════════════════════════════════════════════════════════════════════════════
  //  MAKE BETTER — rung 4, the top of the ratchet. What humans gripe about, love, and keep asking for.
  //  Sum 2026-07-29: "a make this better button that uses human feedback as metrics from available
  //  big data... gets gofai search of good bad and not built yet — gripe, love, wishlists."
  //
  //  THE GATE IS THE FEATURE. 🌍 is DARK until a sweep FINISHES clean. You do not go shopping for
  //  features while the house is on fire. Compile → a disabled person can use it → no bugs → no
  //  style debt → THEN ask the crowd. That gate is what makes this a ratchet, not a treadmill.
  //
  //  ── JS SINKS THE CUE. THE MODEL ONLY READS. ────────────────────────────────────────────────
  //  Three searches, all pre-known: what people hate, what they love, what nobody ships. A shot you
  //  can pretrain is a shot JS takes — no model, no card, no miss. So `searchWeb()` fetches, and
  //  squiggy's only job is distilling text it was HANDED. That is the whole design, and it buys
  //  three things at once:
  //
  //    1. A LOCAL MODEL CAN SEARCH. (Sum: "why can't a local model access websearch, that is a bug
  //       not a feature." He was right.) Native provider search needs anthropic or openrouter, so
  //       the old draft delegated to coder. But search is a fetch, not a provider capability —
  //       window.searchWeb has FOUR engines and two of them are keyless, and on Tauri the same call
  //       routes through Rust with no CORS at all. Nothing about it needs a cloud model.
  //    2. NO BROKEN DEPENDENCY. Monaco ships standalone — it may not have coder, or any other card.
  //       Depending on another card's agent was a cross-wall runtime dependency, exactly what the
  //       sync doctrine forbids: share DATA, never runtime. Rung 4 now uses MC_SQUIGGY, Monaco's
  //       own helper, and degrades with one honest sentence if searchWeb isn't in the build.
  //    3. CITATIONS WE CAN CHECK. We fetched the results, so we know the real urls. A url the model
  //       claims that does NOT appear in what we handed it gets downgraded to INFERRED. The model
  //       cannot forge a citation, because the evidence is on our side of the seam.
  //
  //  THE LABELS, and they are not decoration:
  //    CITED    a url that appears in the results WE fetched. verified, not self-reported.
  //    PATTERN  no url, but it names a specific product or thread. probably real, unverified.
  //    INFERRED the model's own prior. the honest label for a guess, applied by us when it fails
  //             to point at anything we actually retrieved.
  // ═══════════════════════════════════════════════════════════════════════════════════════════════

  // engines in order of quality, ending on two that need NO KEY — so this never hard-fails.
  const BETTER_ENGINES = ['tavily', 'duckduckgo', 'wikipedia']   // jina cut 2026-08-28

  // ── what IS this thing? the file's own IC header exists to answer exactly this ────────────────
  function betterSubject(src, fn) {
    for (const l of src.split('\n').slice(0, 30)) {
      const m = /^\s*(?:\/\/|#|\*)\s*(.+?)\s*$/.exec(l)
      if (!m) continue
      const s = m[1].replace(/^[═─━|/*\s]+|[═─━|/*\s]+$/g, '').split(/\s+[—–(]\s*/)[0].trim()
      if (s.length > 5 && s.length < 60 && !/^(page|lines|search:|sum |written)/i.test(s)) return s
    }
    return fn.replace(/\.[a-z]+$/i, '').replace(/[-_]/g, ' ')
  }

  const betterQueries = subject => [
    ['GRIPE', subject + ' biggest complaints problems'],
    ['LOVE', subject + ' best loved feature why people use it'],
    ['WISH', subject + ' feature requests what is missing']
  ]

  function betterPrompt(subject, blocks) {
    return `I am building this: ${subject}

Below are LIVE WEB RESULTS I already fetched for you. Read only these. Do not invent anything.

${blocks}

Report findings ONE PER LINE, nothing else — no preamble, no summary, no fences.

FORMAT, exactly:
[GRIPE|<TAG>] <what humans hate, one sentence> :: <url from above, or a source name>
[LOVE|<TAG>] <the feature they will not give up> :: <url from above, or a source name>
[WISH|<TAG>] <what they keep asking for that nobody ships> :: <url from above, or a source name>

<TAG> is your honesty label:
  CITED    — it came from a url in the results above. Paste that exact url after the ::
  PATTERN  — no url, but you can name the specific product or thread. Name it after the ::
  INFERRED — your own prior, not in the results above. Write :: no source

Six to ten lines. Concrete beats broad — "the export silently drops layer names" is worth ten of
"users want better UX". A finding I cannot act on this week is not a finding.
If the results above are too thin to work with, say so in one plain line and stop.`
  }

  function betterParse(text) {
    const out = []
    String(text || '').split('\n').forEach(raw => {
      const m = /^\s*\[(GRIPE|LOVE|WISH)\|(CITED|PATTERN|INFERRED)\]\s*(.+?)\s*(?:::\s*(.*))?$/.exec(raw)
      if (m) out.push({ kind: 'CROWD', line: 0, band: m[1], tag: m[2], why: m[3].trim(), src: (m[4] || '').trim() })
    })
    return out
  }

  // ── the button ───────────────────────────────────────────────────────────────────────────────
  async function sqBetter() {
    // THE GATE. Not a nudge — a refusal, with the count, so you know what stands between you and it.
    const st = window.SQUIGGY_SWEEP.state(), clean = window.SQUIGGY_SWEEP.clean()
    if (!clean) {
      const n = st ? st.items.length : 0
      sqChatLog('assistant', n
        ? `🌍 locked. ${n} finding(s) still standing — the ratchet only turns one way. clear the sweep, then the crowd gets a vote.`
        : '🌍 locked. press 🔍 check work first — make better opens only after a sweep comes back clean.')
      return
    }
    if (!window.searchWeb) { sqChatLog('assistant', '🌍 no search in this build (window.searchWeb is missing) — rung 4 needs it. everything below still works.'); return }
    if (!_sqChatOn) toggleSqChat()

    const t = active(), fn = (t && t.filename) || 'code'
    const src = editor ? editor.getValue() : (t && t.content) || ''
    const subject = betterSubject(src, fn)
    const queries = betterQueries(subject)

    // SHOW THE QUERIES BEFORE SPENDING ANYTHING. If the subject is wrong, you can see it's wrong
    // and say so in the chat instead of reading ten findings about the wrong thing.
    sqChatLog('assistant', `🌍 ${fn} is clean, so: what do humans actually want from this?\nsubject: "${subject}"\n` + queries.map(q => '  · ' + q[1]).join('\n'))
    const bubble = sqChatLog('assistant', 'searching…')

    // JS TAKES THE SHOTS. Each query walks the engine list until one answers — the last two need no key.
    const results = [], urls = []
    for (const [band, q] of queries) {
      let text = '', used = ''
      for (const eng of BETTER_ENGINES) {
        try { text = await window.searchWeb(eng, q); if (text && String(text).trim()) { used = eng; break } } catch (_) {}
      }
      if (bubble) bubble.textContent = `searched ${band.toLowerCase()}${used ? ' via ' + used : ' — nothing answered'}…`
      if (!text) continue
      results.push(`### ${band} — "${q}" (via ${used})\n${text}`)
      ;(String(text).match(/https?:\/\/[^\s)"'<>]+/g) || []).forEach(u => urls.push(u))
    }
    if (!results.length) { if (bubble) bubble.textContent = 'no engine answered. tavily wants a free key in ⚙ settings; duckduckgo and wikipedia are keyless but thin on niche topics.'; return }

    if (bubble) bubble.textContent = `${urls.length} source(s) fetched. asking squiggy to distill…`
    let acc = ''
    try {
      const res = await window.engineRaw({ agentId: MC_SQUIGGY, messages: [{ role: 'user', content: betterPrompt(subject, results.join('\n\n')) }], onChunk: c => { acc += c } })
      acc = (res && res.text) || acc
    } catch (e) { if (bubble) bubble.textContent = '⚠ ' + String((e && e.message) || e); return }

    const found = betterParse(acc)
    if (!found.length) { if (bubble) bubble.textContent = 'nothing came back in the format — the raw reply is above. read it yourself rather than trust my parse.'; return }

    // VERIFY THE CITATIONS AGAINST WHAT WE ACTUALLY FETCHED. A url we never retrieved is not a
    // citation, it is a sentence with a url in it. Downgrade it and say we did.
    let forged = 0
    found.forEach(x => {
      if (x.tag !== 'CITED') return
      const u = (x.src.match(/https?:\/\/[^\s)"'<>]+/) || [])[0]
      if (!u || !urls.some(k => k.indexOf(u.slice(0, 40)) === 0 || u.indexOf(k.slice(0, 40)) === 0)) { x.tag = 'INFERRED'; x.src = 'no source (claimed a url we never fetched)'; forged++ }
    })
    const cited = found.filter(x => x.tag === 'CITED').length
    const note = `${cited} of ${found.length} carry a url we actually fetched.` + (forged ? ` ${forged} claimed a url that was not in the results — downgraded to INFERRED.` : '')

    const md = `# make better — ${fn}\n\n${new Date().toISOString()}\nsubject: ${subject}\nsearched by: js (${BETTER_ENGINES.join(' → ')}) · distilled by: squiggy\n\n${note}\n\n` +
      ['GRIPE', 'LOVE', 'WISH'].map(b => {
        const rows = found.filter(x => x.band === b)
        return rows.length ? `\n## ${b}\n\n` + rows.map(x => `- **[${x.tag}]** ${x.why}${x.src ? `\n  ${x.src}` : ''}`).join('\n') + '\n' : ''
      }).join('') +
      `\n---\n\n## the queries\n\n` + queries.map(q => '- `' + q[1] + '`').join('\n') + '\n'
    const path = 'sweeps/better-' + fn.replace(/[^\w.-]/g, '_') + '.md'
    try { const c = window.__TAURI__ && (window.__TAURI__.core || window.__TAURI__); if (c && c.invoke) await c.invoke('sandbox_write', { name: path, content: md }) } catch (_) {}

    // WISHLIST.md is now fed by CITED HUMAN WANTS, not machine daydreams — the whole point of
    // cutting the old wish rung. A wish with a url behind it is a spec; one without is a mood.
    const wishes = found.filter(x => x.band === 'WISH' && x.tag !== 'INFERRED')
    if (wishes.length) {
      try {
        const c = window.__TAURI__ && (window.__TAURI__.core || window.__TAURI__)
        const prev = (window.SANDBOX && window.SANDBOX['WISHLIST.md'] && window.SANDBOX['WISHLIST.md'].data) || '# wishlist — what humans asked for, with receipts\n'
        if (c && c.invoke) await c.invoke('sandbox_write', { name: 'WISHLIST.md', content: prev + wishes.map(w => `- (${fn}) [${w.tag}] ${w.why} — ${w.src}\n`).join('') })
      } catch (_) {}
    }

    if (bubble) bubble.textContent = `${found.length} from the crowd — ${note} saved to ${path}. press 🔍 to walk them.`
    found.forEach(x => { x.file = fn; x.why = `${x.band} [${x.tag}] ${x.why}` + (x.src ? ` — ${x.src}` : '') })
    window.SQUIGGY_SWEEP.adopt(found, path)
  }

  window.SQUIGGY_BETTER = { run: sqBetter }
